class FarmersHubApp extends StatelessWidget {
  const FarmersHubApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner:false,title:'FarmersHub GH',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:farmerGreen),scaffoldBackgroundColor:pageBg),home:const AuthGate());
