class AuthGate extends StatelessWidget { const AuthGate({super.key}); @override Widget build(BuildContext context)=>StreamBuilder<User?>(stream:FirebaseAuth.instance.authStateChanges(),builder:(context,s){if(s.connectionState==ConnectionState.waiting)return const Scaffold(body:Center(child:CircularProgressIndicator()));return s.data==null?const LoginPage():const MainShell();});}
String authMessage(FirebaseAuthException e){if(e.code=='invalid-credential'||e.code=='wrong-password')return'Incorrect email or password.';if(e.code=='email-already-in-use')return'An account already exists with this email.';if(e.code=='weak-password')return'Choose a stronger password.';return e.message??'Unable to complete this request.';}
class LoginPage extends StatefulWidget{const LoginPage({super.key});@override State<LoginPage> createState()=>_LoginPageState();}
class _LoginPageState extends State<LoginPage>{final email=TextEditingController(),password=TextEditingController();String? error;Future<void> login()async{try{await FirebaseAuth.instance.signInWithEmailAndPassword(email:email.text.trim(),password:password.text);}on FirebaseAuthException catch(e){setState(()=>error=authMessage(e));}}@override Widget build(BuildContext context)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:430),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.eco,size:72,color:farmerGreen),const Text('FarmersHub GH',textAlign:TextAlign.center,style:TextStyle(fontSize:28,fontWeight:FontWeight.w900,color:darkGreen)),const Text('Know Your Farm. Grow Your Profit.',textAlign:TextAlign.center),const SizedBox(height:30),TextField(controller:email,decoration:const InputDecoration(labelText:'Email Address')),const SizedBox(height:12),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password')),if(error!=null)Text(error!,style:const TextStyle(color:Colors.red)),FilledButton(onPressed:login,child:const Text('Login')),TextButton(onPressed:()async{if(email.text.trim().isNotEmpty)await FirebaseAuth.instance.sendPasswordResetEmail(email:email.text.trim());},child:const Text('Forgot Password?')),OutlinedButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const RegisterPage())),child:const Text('Create Account'))]))))));}
class RegisterPage extends StatefulWidget{const RegisterPage({super.key});@override State<RegisterPage> createState()=>_RegisterPageState();}
class _RegisterPageState extends State<RegisterPage>{final name=TextEditingController(),phone=TextEditingController(),email=TextEditingController(),password=TextEditingController(),confirm=TextEditingController();String? error;Future<void> save()async{if(password.text!=confirm.text){setState(()=>error='Passwords do not match.');return;}try{final c=await FirebaseAuth.instance.createUserWithEmailAndPassword(email:email.text.trim(),password:password.text);await c.user!.updateDisplayName(name.text.trim());await FirebaseFirestore.instance.collection('users').doc(c.user!.uid).set({'uid':c.user!.uid,'display_name':name.text.trim(),'email':email.text.trim(),'phone_number':phone.text.trim(),'created_time':FieldValue.serverTimestamp()});if(mounted)Navigator.popUntil(context,(r)=>r.isFirst);}on FirebaseAuthException catch(e){setState(()=>error=authMessage(e));}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Create Account')),body:ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Full Name')),TextField(controller:phone,decoration:const InputDecoration(labelText:'Phone Number (optional)')),TextField(controller:email,decoration:const InputDecoration(labelText:'Email Address')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password')),TextField(controller:confirm,obscureText:true,decoration:const InputDecoration(labelText:'Confirm Password')),if(error!=null)Text(error!,style:const TextStyle(color:Colors.red)),FilledButton(onPressed:save,child:const Text('Create Account'))]));}
class MainShell extends StatefulWidget{const MainShell({super.key});@override State<MainShell> createState()=>_MainShellState();}
