class DashboardPage extends StatelessWidget{const DashboardPage({super.key});@override Widget build(BuildContext context){final uid=FirebaseAuth.instance.currentUser!.uid;return SafeArea(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('transactions').where('user_id',isEqualTo:uid).snapshots(),builder:(context,s){final docs=s.data?.docs??[];double income=0,expenses=0;for(final d in docs){final x=d.data(),a=(x['amount']as num?)?.toDouble()??0;if(x['type']=='Income')income+=a;else if(x['type']=='Expense')expenses+=a;}return ListView(padding:const EdgeInsets.all(20),children:[const Text('Welcome to FarmersHub GH',style:TextStyle(fontSize:24,fontWeight:FontWeight.w900)),Card(child:ListTile(title:const Text('Total Balance'),trailing:Text(money.format(income-expenses)))),FilledButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const AddTransactionPage())),child:const Text('Add Transaction')),const Text('Recent Transactions',style:TextStyle(fontSize:18,fontWeight:FontWeight.w900)),...docs.take(8).map((d){final x=d.data();return Card(child:ListTile(title:Text('${x['category']??'Transaction'}'),subtitle:Text('${x['farm_name']??''} • ${x['crop_name']??''}'),trailing:Text(money.format((x['amount']as num?)?.toDouble()??0))));})]);}));}}
class ReportsPage extends StatelessWidget{const ReportsPage({super.key});@override Widget build(BuildContext context){final uid=FirebaseAuth.instance.currentUser!.uid;return SafeArea(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('transactions').where('user_id',isEqualTo:uid).snapshots(),builder:(context,s){double i=0,e=0;for(final d in s.data?.docs??[]){final x=d.data(),a=(x['amount']as num?)?.toDouble()??0;if(x['type']=='Income')i+=a;else if(x['type']=='Expense')e+=a;}return ListView(padding:const EdgeInsets.all(20),children:[const Text('Reports',style:TextStyle(fontSize:27,fontWeight:FontWeight.w900)),Card(child:ListTile(title:const Text('Income'),trailing:Text(money.format(i)))),Card(child:ListTile(title:const Text('Expenses'),trailing:Text(money.format(e)))),Card(child:ListTile(title:const Text('Net Profit'),trailing:Text(money.format(i-e))))]);}));}}
class FarmsPage extends StatelessWidget{const FarmsPage({super.key});@override Widget build(BuildContext context){final uid=FirebaseAuth.instance.currentUser!.uid;return SafeArea(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('farms').where('user_id',isEqualTo:uid).snapshots(),builder:(context,s)=>ListView(padding:const EdgeInsets.all(20),children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text('My Farms',style:TextStyle(fontSize:27,fontWeight:FontWeight.w900)),FilledButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const AddFarmPage())),child:const Text('Add Farm'))]),...(s.data?.docs??[]).map((f){final x=f.data();return Card(child:ListTile(title:Text('${x['name']??'Farm'}'),subtitle:Text('${x['location']??''}'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>CropsPage(farmId:f.id,farmName:'${x['name']??'Farm'}')))));})]));));}}
class AddFarmPage extends StatefulWidget{const AddFarmPage({super.key});@override State<AddFarmPage> createState()=>_AddFarmPageState();}class _AddFarmPageState extends State<AddFarmPage>{final name=TextEditingController(),location=TextEditingController(),size=TextEditingController();Future<void> save()async{final a=double.tryParse(size.text)??0;if(a<=0)return;await FirebaseFirestore.instance.collection('farms').add({'user_id':FirebaseAuth.instance.currentUser!.uid,'name':name.text,'location':location.text,'size_acres':a,'created_time':FieldValue.serverTimestamp()});if(mounted)Navigator.pop(context);}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Register Farm')),body:ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Farm Name')),TextField(controller:location,decoration:const InputDecoration(labelText:'Location')),TextField(controller:size,decoration:const InputDecoration(labelText:'Farm Size (acres)')),FilledButton(onPressed:save,child:const Text('Save Farm'))]));}
