class AddCropPage extends StatefulWidget{final String farmId,farmName;const AddCropPage({super.key,required this.farmId,required this.farmName});@override State<AddCropPage> createState()=>_AddCropPageState();}class _AddCropPageState extends State<AddCropPage>{final crop=TextEditingController(),acreage=TextEditingController(),yieldAmount=TextEditingController(),price=TextEditingController();String unit='bags';Future<void> save()async{await FirebaseFirestore.instance.collection('crops').add({'user_id':FirebaseAuth.instance.currentUser!.uid,'farm_id':widget.farmId,'farm_name':widget.farmName,'crop_name':crop.text,'acreage':double.tryParse(acreage.text)??0,'expected_yield':double.tryParse(yieldAmount.text)??0,'yield_unit':unit,'expected_selling_price':double.tryParse(price.text)??0,'status':'Growing','created_time':FieldValue.serverTimestamp()});if(mounted)Navigator.pop(context);}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Add Crop')),body:ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:crop,decoration:const InputDecoration(labelText:'Crop Name')),TextField(controller:acreage,decoration:const InputDecoration(labelText:'Acreage')),TextField(controller:yieldAmount,decoration:const InputDecoration(labelText:'Expected Yield')),DropdownButtonFormField<String>(initialValue:unit,items:const['bags','kg','tonnes','crates','units'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>unit=v??unit)),TextField(controller:price,decoration:InputDecoration(labelText:'Expected Selling Price per $unit (GH₵)')),FilledButton(onPressed:save,child:const Text('Save Crop'))]));}
class CropProfitPage extends StatelessWidget{final String cropId;final Map<String,dynamic> crop;const CropProfitPage({super.key,required this.cropId,required this.crop});Widget stat(String l,double v)=>Card(child:ListTile(title:Text(l),trailing:Text(money.format(v),style:const TextStyle(fontWeight:FontWeight.w900))));@override Widget build(BuildContext context){final uid=FirebaseAuth.instance.currentUser!.uid;return Scaffold(appBar:AppBar(title:Text('${crop['crop_name']??'Crop'} Profitability')),floatingActionButton:FloatingActionButton.extended(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>AddTransactionPage(initialFarmId:'${crop['farm_id']??''}',initialFarmName:'${crop['farm_name']??''}',initialCropId:cropId,initialCropName:'${crop['crop_name']??''}'))),label:const Text('Add Transaction')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('transactions').where('user_id',isEqualTo:uid).snapshots(),builder:(context,s){double income=0,expenses=0;for(final d in s.data?.docs??[]){final x=d.data();if(x['crop_id']!=cropId)continue;final a=(x['amount']as num?)?.toDouble()??0;if(x['type']=='Income')income+=a;else if(x['type']=='Expense')expenses+=a;}final p=ProfitabilitySnapshot(income:income,expenses:expenses,acreage:(crop['acreage']as num?)?.toDouble()??0,expectedYield:(crop['expected_yield']as num?)?.toDouble()??0,expectedSellingPrice:(crop['expected_selling_price']as num?)?.toDouble()??0);final unit='${crop['yield_unit']??'unit'}';return ListView(padding:const EdgeInsets.all(20),children:[Text('${crop['crop_name']??'Crop'} • ${crop['farm_name']??''}',style:const TextStyle(fontSize:22,fontWeight:FontWeight.w900)),stat('Recorded Income',p.income),stat('Recorded Expenses',p.expenses),stat('Current Net Profit',p.netProfit),stat('Profit per acre',p.profitPerAcre),stat('Cost per acre',p.costPerAcre),stat('Break-even price per $unit',p.breakEvenPrice),stat('Expected revenue',p.expectedRevenue),stat('Projected profit',p.projectedProfit),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Farmer Insight',style:TextStyle(fontWeight:FontWeight.w900,fontSize:18)),const SizedBox(height:8),Text(p.recommendation(unit)),if(p.expectedRevenue>0)Padding(padding:const EdgeInsets.only(top:8),child:Text('Projected margin: ${p.projectedMarginPercent.toStringAsFixed(1)}%'))])))]);}));}}
class AddTransactionPage extends StatefulWidget{final String? initialFarmId,initialFarmName,initialCropId,initialCropName;const AddTransactionPage({super.key,this.initialFarmId,this.initialFarmName,this.initialCropId,this.initialCropName});@override State<AddTransactionPage> createState()=>_AddTransactionPageState();}class _AddTransactionPageState extends State<AddTransactionPage>{String? type,category,payment,farmId,farmName,cropId,cropName;final amount=TextEditingController(),notes=TextEditingController();@override void initState(){super.initState();farmId=widget.initialFarmId;farmName=widget.initialFarmName;cropId=widget.initialCropId;cropName=widget.initialCropName;}Future<void> save()async{final v=double.tryParse(amount.text)??0;if(v<=0||type==null||category==null||payment==null)return;await FirebaseFirestore.instance.collection('transactions').add({'user_id':FirebaseAuth.instance.currentUser!.uid,'farm_id':farmId??'','farm_name':farmName??'','crop_id':cropId??'','crop_name':cropName??'','type':type,'category':category,'amount':v,'payment_method':payment,'notes':notes.text,'date':Timestamp.now(),'created_time':FieldValue.serverTimestamp()});if(mounted)Navigator.pop(context);}@override Widget build(BuildContext context){final uid=FirebaseAuth.instance.currentUser!.uid;return Scaffold(appBar:AppBar(title:const Text('Add Transaction')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('farms').where('user_id',isEqualTo:uid).snapshots(),builder:(context,s){final farms=s.data?.docs??[];return ListView(padding:const EdgeInsets.all(20),children:[DropdownButtonFormField<String>(initialValue:type,decoration:const InputDecoration(labelText:'Type'),items:const['Income','Expense'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>type=v)),DropdownButtonFormField<String>(initialValue:farmId,decoration:const InputDecoration(labelText:'Farm (optional)'),items:farms.map((f)=>DropdownMenuItem(value:f.id,child:Text('${f.data()['name']??'Farm'}'))).toList(),onChanged:(v){final m=farms.where((f)=>f.id==v);setState((){farmId=v;farmName=m.isEmpty?'':'${m.first.data()['name']??''}';cropId=null;cropName=null;});}),if(farmId!=null&&farmId!.isNotEmpty)StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('crops').where('user_id',isEqualTo:uid).where('farm_id',isEqualTo:farmId).snapshots(),builder:(context,cs){final crops=cs.data?.docs??[];return DropdownButtonFormField<String>(initialValue:cropId,decoration:const InputDecoration(labelText:'Crop (optional)'),items:crops.map((c)=>DropdownMenuItem(value:c.id,child:Text('${c.data()['crop_name']??'Crop'}'))).toList(),onChanged:(v){final m=crops.where((c)=>c.id==v);setState((){cropId=v;cropName=m.isEmpty?'':'${m.first.data()['crop_name']??''}';});});}),DropdownButtonFormField<String>(initialValue:category,decoration:const InputDecoration(labelText:'Category'),items:const['Sales','Seeds','Fertilizer','Labour','Feed','Transport','Equipment','Fuel','Harvest','Other'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>category=v)),TextField(controller:amount,decoration:const InputDecoration(labelText:'Amount (GH₵)')),DropdownButtonFormField<String>(initialValue:payment,decoration:const InputDecoration(labelText:'Payment Method'),items:const['Cash','Mobile Money','Bank Transfer'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>payment=v)),TextField(controller:notes,decoration:const InputDecoration(labelText:'Notes (optional)')),FilledButton(onPressed:save,child:const Text('Save Transaction'))]);}));}}
